"""Todo command-line tool."""
import argparse
import sys
from pathlib import Path

STORE = Path("tasks.txt")


def load(path=STORE):
    if not path.exists():
        return []
    return [line for line in path.read_text().splitlines() if line]


def add(task, path=STORE):
    tasks = load(path)
    tasks.append(task)
    path.write_text("\n".join(tasks) + "\n")


def render(tasks):
    return [f"{index}. {task}" for index, task in enumerate(tasks, 1)]


def main(argv=None, path=STORE, out=sys.stdout):
    parser = argparse.ArgumentParser(prog="todo")
    commands = parser.add_subparsers(dest="command", required=True)
    add_parser = commands.add_parser("add")
    add_parser.add_argument("task")
    commands.add_parser("list")
    args = parser.parse_args(argv)
    if args.command == "add":
        add(args.task, path)
    else:
        for line in render(load(path)):
            print(line, file=out)


if __name__ == "__main__":
    main()

