"""Ledger reports."""

TAX_RATE = 0.21


def monthly_report(entries, month):
    """Return net, tax, and gross for entries dated in month (YYYY-MM)."""
    net = sum(amount for date, amount in entries if date.startswith(month))
    tax = round(net * TAX_RATE, 2)
    return {"period": month, "net": round(net, 2), "tax": tax, "gross": round(net + tax, 2)}


def annual_report(entries, year):
    """Return net, tax, and gross for entries dated in year (YYYY)."""
    net = sum(amount for date, amount in entries if date.startswith(year))
    tax = round(net * TAX_RATE, 2)
    return {"period": year, "net": round(net, 2), "tax": tax, "gross": round(net + tax, 2)}

