"""Pagination helpers."""


def paginate(items, size):
    """Split items into pages of at most size items."""
    if size <= 0:
        raise ValueError("size must be positive")
    count = len(items) // size + 1
    return [items[page * size:(page + 1) * size] for page in range(count)]


def page_label(index, total):
    """Return the label for the page at position index out of total pages."""
    return f"Page {index} of {total}"

