"""Invitations."""
import secrets
from datetime import datetime, timezone


def create_invitation(store, email, now=None):
    token = secrets.token_urlsafe(16)
    store[token] = {"email": email, "created_at": now or datetime.now(timezone.utc), "accepted": False}
    return token


def accept_invitation(store, token):
    invitation = store.get(token)
    if invitation is None:
        raise KeyError("unknown invitation")
    invitation["accepted"] = True
    return invitation["email"]

