// Invitations.
const FOURTEEN_DAYS_MS = 14 * 24 * 60 * 60 * 1000;

function isExpired(invitation, now) {
  return now - invitation.createdAt > FOURTEEN_DAYS_MS;
}

function accept(store, token) {
  const invitation = store.get(token);
  if (!invitation) throw new Error("unknown invitation");
  invitation.accepted = true;
  return invitation.email;
}

module.exports = { isExpired, accept };

