"""Invoice export."""
import csv
import sys


def line_total(quantity, unit_price):
    return round(quantity * unit_price, 2)


def invoice_total(lines):
    return round(sum(quantity * unit_price for quantity, unit_price in lines), 2)


def load(path):
    with open(path, newline="") as handle:
        return [(int(row["quantity"]), float(row["unit_price"])) for row in csv.DictReader(handle)]


def export(lines, out=sys.stdout):
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["quantity", "unit_price", "line_total"])
    for quantity, unit_price in lines:
        writer.writerow([quantity, unit_price, f"{line_total(quantity, unit_price):.2f}"])
    writer.writerow(["", "total", f"{invoice_total(lines):.2f}"])


if __name__ == "__main__":
    export(load(sys.argv[1]))

