import sys
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import lists


class ListTests(unittest.TestCase):
    def setUp(self):
        self.store = {}
        lists.create_list(self.store, "groceries", owner="ana")
        lists.share_list(self.store, "groceries", "ana", with_user="ben")

    def test_shared_user_can_add_items(self):
        lists.add_item(self.store, "groceries", "ben", "milk")
        self.assertEqual(self.store["groceries"]["items"], ["milk"])

    def test_stranger_cannot_add_items(self):
        with self.assertRaises(lists.Forbidden):
            lists.add_item(self.store, "groceries", "cy", "milk")

    def test_owner_can_delete(self):
        lists.delete_list(self.store, "groceries", "ana")
        self.assertNotIn("groceries", self.store)

    def test_stranger_cannot_delete(self):
        with self.assertRaises(lists.Forbidden):
            lists.delete_list(self.store, "groceries", "cy")


if __name__ == "__main__":
    unittest.main()
